import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int maxRun = 0, totalWords = 0, outsideCount = 0, insideCount = 0;
        boolean inParen = false;
        String str = br.readLine();
        char[] arr = str.toCharArray();

        for (int i = 0; i < n; i++) {
            char ch = arr[i];
            if (ch == '(') {
                inParen = true;
                outsideCount = 0;
            } else if (ch == ')') {
                inParen = false;
                if (insideCount > 0) {
                    totalWords++;
                    insideCount = 0;
                }
            } else {
                if (inParen) {
                    if (ch != '_') {
                        insideCount++;
                    } else {
                        if (insideCount > 0) {
                            totalWords++;
                            insideCount = 0;
                        }
                    }
                } else {
                    if (ch != '_') {
                        outsideCount++;
                    } else {
                        outsideCount = 0;
                    }
                }
            }
            if (outsideCount >= maxRun) {
                maxRun = outsideCount;
            }
        }
        System.out.println(maxRun);
        System.out.println(totalWords);
    }
}
